package application.domain.services.fulfillment;
import application.domain.model.*; import application.domain.ports.in.*; import application.domain.ports.out.*; import application.domain.services.ServiceSupport; import application.domain.exceptions.*; import java.util.*;
public class CreateShipmentService implements CreateShipmentUseCase { private final OrderRepositoryPort orders; private final ShipmentRepositoryPort shipments; private final OperationAuditPort audit; public CreateShipmentService(OrderRepositoryPort o,ShipmentRepositoryPort s,OperationAuditPort a){orders=o;shipments=s;audit=a;}
 public Shipment createShipment(User actor,String oid,String sid,Address address){ServiceSupport.role(actor,"ADMIN","EMPLOYEE","SELLER");Order o=ServiceSupport.required(orders.findById(oid),"Order",oid);if(o.getStatus()!=DomainTypes.OrderStatus.PAID&&o.getStatus()!=DomainTypes.OrderStatus.PROCESSING)throw new DomainRuleException("Order must be paid before shipment");if(shipments.findByOrder(o).isPresent())throw new DomainRuleException("Shipment already exists");Shipment s=shipments.save(new Shipment(sid,o,address));o.changeStatus(DomainTypes.OrderStatus.PROCESSING);orders.update(o);audit.record(actor,"CREATE_SHIPMENT",sid,Map.of("orderId",oid));return s;}
}
